// ianox — UI strings.
// The code uses the English text as the key; locales/*.po hold the
// translations and the JSON is generated by `npm run i18n`.
import { app } from "./app.svelte";
import es from "./locales/es.json";
import en from "./locales/en.json";

type Dict = Record<string, string>;

const base: Dict = en;
const dicts: Record<string, Dict> = { en, es };

export function t(key: string, vars?: Record<string, string>): string {
  const lang = app.language === "es" ? "es" : "en";
  const value = dicts[lang]?.[key] ?? base[key] ?? key;
  if (!vars) return value;
  return value.replace(/\{(\w+)\}/g, (_, name: string) => vars[name] ?? `{${name}}`);
}
